document.body.innerHTML="\n<header><div><div class=\"eyebrow\">BADGER \u00b7 INVENTORY SERVICE, INC.</div><h1>Shift Crew Planner</h1><p>Select your store. Build your crew. Preview the full visit.</p></div><div class=\"auth-status\"><span id=\"userStatus\"></span><button id=\"signOut\" type=\"button\">Sign Out</button></div></header>\n<main><section class=\"release-bar\"><strong>Shared weekly plan</strong><span id=\"snapshotInfo\"></span><button id=\"resetPlan\" type=\"button\">Reset plan</button></section>\n<nav aria-label=\"Planner sections\"><a href=\"#plan\" data-view=\"plan\">Crew Planner</a><a href=\"#compare\" data-view=\"compare\">Two-Store Assignment</a><a href=\"#history\" data-view=\"history\">Forecast History</a><a href=\"#insights\" data-view=\"insights\">Historical Accuracy</a></nav>\n<p id=\"notice\" role=\"status\" aria-live=\"polite\"></p>\n<section id=\"view-plan\" class=\"view\"><div class=\"columns\"><form id=\"planForm\" class=\"card\" novalidate><h2>Setup</h2>\n<div class=\"step-label\">1 \u00b7 Select Store</div><label>Account<select id=\"account\"></select></label><label>Find a store<input id=\"storeFilter\" type=\"search\" placeholder=\"Search account or store name\"></label><button id=\"clearStoreSearch\" class=\"compact\" type=\"button\">Clear search</button><label>Store<select id=\"store\" required></select></label><p id=\"storeCount\" class=\"muted small\"></p><div id=\"storeSummary\" class=\"context\">Select a store to view history.</div>\n<div class=\"row\"><label>Inventory date<input id=\"date\" type=\"date\" required></label><label>Scheduled start<input id=\"time\" type=\"time\" value=\"06:00\" required></label></div><label class=\"check\"><input id=\"fullOnsiteMode\" type=\"checkbox\" checked>Use integrated full-onsite model</label><p class=\"small muted\">Uncheck to use the original attendance-proxy reference. Manual changes are explicitly labelled scenario estimates.</p><label class=\"check\"><input id=\"useModas\" type=\"checkbox\">Count inventory with Modas</label><p id=\"countingModeHint\" class=\"small muted\"></p>\n<div class=\"step-label\">2 \u00b7 Goal</div><div class=\"row\"><label>Custom target (hours)<input id=\"targetValue\" type=\"number\" min=\"0\" step=\"0.25\" placeholder=\"Optional\"></label><label>Goal type<select id=\"planningMode\"><option value=\"duration\">In-Store Time</option><option value=\"manhours\">Man-Hours</option></select></label></div><p id=\"goalHint\" class=\"small muted\">Set an optional target to compare your plan.</p>\n<details class=\"adjustments\"><summary>Production adjustments</summary><div class=\"row\"><label>Production Shrink %<input id=\"shrinkPercent\" type=\"number\" min=\"0\" max=\"100\" step=\"1\" value=\"0\"></label><label>Apply shrink to<select id=\"shrinkMode\"><option value=\"all\">All selected crew</option><option value=\"selected\">Checked crew only</option><option value=\"none\">Nobody</option></select></label></div><div id=\"shrinkEmployees\" class=\"role-checklist\"></div><label class=\"check\"><input id=\"recentProduction\" type=\"checkbox\">Use most recent account production for arrowed employees</label><p class=\"small muted\">Uses the original planner\u2019s latest-account rate resolver. Shrink and contributions affect its reference estimate; they do not retrain the integrated model.</p></details>\n<div class=\"step-label\">3 \u00b7 Choose Crew</div><label>Find an employee<input id=\"employeeFilter\" type=\"search\" placeholder=\"Search crew member\"></label><label>Add by name<input id=\"crewNames\" placeholder=\"Full names separated by commas\"></label><div class=\"actions\"><button id=\"addNames\" type=\"button\">Add names</button><button id=\"lastCrew\" type=\"button\">Use Last Crew</button><button id=\"clearEmployees\" type=\"button\">Clear crew</button></div><p id=\"selectedCrewSummary\" aria-live=\"polite\">No crew selected.</p><div id=\"crew\" class=\"crew\"></div><p id=\"crewCount\" class=\"small muted\"></p>\n<div class=\"step-label\">4 \u00b7 Assign Roles</div><label>Supervisor<select id=\"supervisor\"></select></label><label>Supervisor contribution<select id=\"supervisorMode\"><option value=\"full\">Full Contribution</option><option value=\"p70\">70% Contribution</option><option value=\"p50\" selected>50% Contribution</option><option value=\"p30\">30% Contribution</option><option value=\"none\">None (0%)</option></select></label>\n<details open><summary>RX</summary><label>RX employees<select id=\"rx\" multiple size=\"3\"></select></label><label>RX contribution<select id=\"rxMode\"><option value=\"p70\">70%</option><option value=\"p50\" selected>50%</option><option value=\"p30\">30%</option><option value=\"full\">Full</option><option value=\"none\">None (0%)</option></select></label></details>\n<details><summary>Training Adjustments</summary><label>Employees in training<select id=\"training\" multiple size=\"3\"></select></label><label>Training contribution<select id=\"trainingMode\"><option value=\"p70\" selected>70%</option><option value=\"p50\">50%</option><option value=\"p30\">30%</option><option value=\"full\">Full</option><option value=\"none\">None (0%)</option></select></label></details>\n<details><summary>Early Leave / Late Arrival</summary><label>Affected employees<select id=\"earlyLate\" multiple size=\"3\"></select></label><label>Contribution while available<select id=\"earlyLateMode\"><option value=\"p70\">70%</option><option value=\"p50\" selected>50%</option><option value=\"p30\">30%</option><option value=\"full\">Full</option><option value=\"none\">None (0%)</option></select></label></details>\n<button id=\"calculate\" class=\"primary\" disabled>Calculate Plan Preview</button><p class=\"small muted\">Valid input changes also recalculate automatically. No file uploads are available.</p></form>\n<section class=\"card result\"><div class=\"eyebrow\">Review</div><h2>Plan Preview</h2><p id=\"estimateKind\" class=\"pill\"></p><h3>Estimated On-Site Time</h3><div id=\"prediction\">Select a store and crew to begin.</div><div class=\"metric-grid\"><div class=\"context\"><h3>Labor Hours</h3><strong id=\"labor\">\u2014</strong><p class=\"small muted\">Estimated duration \u00d7 headcount, assuming everyone remains for the visit; the same definition as the original duration planner.</p></div><div class=\"context\"><h3>Effective Counting Hours</h3><strong id=\"effectiveLabor\">\u2014</strong><p class=\"small muted\">Duration \u00d7 assumed counting contributions. A scenario projection, not attendance hours.</p></div></div><div class=\"context\"><h3>Recommendation</h3><strong id=\"recommendation\">Choose Store and Crew</strong><p id=\"delta\"></p><button id=\"suggestStaffing\" type=\"button\" disabled>Explore staffing changes for goal</button><p id=\"staffingSuggestion\" class=\"small\"></p></div>\n<p id=\"referenceComparison\" class=\"comparison\"></p><p id=\"scenarioExplanation\" class=\"small muted\"></p><details><summary>Historical Error Range</summary><div id=\"historicalRange\"></div><p class=\"small muted\">Archived original-reference error offsets are historical evidence. No validated prediction interval exists for the integrated model, refreshed bundle or manual scenarios.</p></details>\n<button id=\"save\" type=\"button\" disabled>Save previsit forecast</button><label class=\"check\"><input id=\"autoSave\" type=\"checkbox\" checked>Automatically save valid future plans</label><p id=\"saveStatus\" class=\"small muted\">Future plans with assigned roles are saved in this browser. Past-start previews remain exploratory.</p>\n<details open><summary>Why this estimate?</summary><p id=\"whyEstimate\"></p></details><details><summary>Detailed Background</summary><div id=\"background\"></div></details><details open><summary>Crew Production View</summary><p class=\"small muted\">Derived planning rates and projected pieces under the selected assumptions; not promised production.</p><div class=\"table-scroll\"><table><thead><tr><th>Rank</th><th>Employee</th><th>Role / factor</th><th>Pieces/hr</th><th>Most Recent Account</th><th>Adjusted Pieces/hr</th><th>Projected Pieces</th><th>Evidence</th></tr></thead><tbody id=\"production\"></tbody></table></div></details><details><summary>Last Crew</summary><p id=\"lastCrewSummary\"></p></details><p class=\"small muted\">The 19-minute average-error goal remains unmet. Retrospective staffing comparisons do not establish causal effects.</p></section></div></section>\n<section id=\"view-compare\" class=\"view hidden card\"><h2>Two-Store Suggested Assignment</h2><p>Pick two stores and goals, select available crew, then assign separate supervisors. Linked employees stay together; locked employees stay at their designated store.</p><div class=\"row\"><label>Store A<select id=\"compareStoreA\"></select></label><label>Store B<select id=\"compareStoreB\"></select></label></div><div class=\"row\"><label>Goal A<input id=\"compareGoalA\" type=\"number\" min=\"0.25\" step=\"0.25\" value=\"4\"></label><label>Goal B<input id=\"compareGoalB\" type=\"number\" min=\"0.25\" step=\"0.25\" value=\"4\"></label></div><div class=\"row\"><label>Goal type<select id=\"compareGoalMode\"><option value=\"duration\">In-Store Time</option><option value=\"manhours\">Man-Hours</option></select></label><label>Inventory date<input id=\"compareDate\" type=\"date\"></label></div><div class=\"actions\"><button id=\"compareUseCrew\" type=\"button\">Use current selected crew</button><button id=\"compareClear\" type=\"button\">Clear Available Employees</button></div><label>Find available employees<input id=\"compareEmployeeFilter\" type=\"search\"></label><div id=\"compareEmployees\" class=\"crew\"></div><p id=\"compareCount\"></p><div class=\"row\"><label>Supervisor A<select id=\"compareSupervisorA\"></select></label><label>Supervisor B<select id=\"compareSupervisorB\"></select></label></div><div class=\"row\"><label>Supervisor contribution A<select id=\"compareSupervisorModeA\"><option value=\"full\">Full</option><option value=\"p70\">70%</option><option value=\"p50\" selected>50%</option><option value=\"p30\">30%</option><option value=\"none\">None</option></select></label><label>Supervisor contribution B<select id=\"compareSupervisorModeB\"><option value=\"full\">Full</option><option value=\"p70\">70%</option><option value=\"p50\" selected>50%</option><option value=\"p30\">30%</option><option value=\"none\">None</option></select></label></div><div class=\"row\"><label>Linked Employees (stay together)<textarea id=\"linkedGroups\" rows=\"3\" placeholder=\"Jerry + Celina, one group per line\"></textarea></label><div><label>Locked To Store A<textarea id=\"lockedA\" rows=\"2\" placeholder=\"One full name per line\"></textarea></label><label>Locked To Store B<textarea id=\"lockedB\" rows=\"2\" placeholder=\"One full name per line\"></textarea></label></div></div><div class=\"row\"><label>Shared RX employees<select id=\"compareRx\" multiple size=\"3\"></select></label><label>Shared training employees<select id=\"compareTraining\" multiple size=\"3\"></select></label></div><label>Shared early/late employees<select id=\"compareEarlyLate\" multiple size=\"3\"></select></label><p class=\"small muted\">Shared RX, training and early/late contribution percentages, Modas/latest-account and shrink settings come from Setup. Each store receives only roles belonging to its assigned crew. The same model/scenario distinction applies.</p><button id=\"suggestAssignment\" type=\"button\" class=\"primary\">Suggest Assignment</button><p id=\"allocationStatus\" role=\"status\" aria-live=\"polite\"></p><div id=\"allocationResult\"></div></section>\n<section id=\"view-history\" class=\"view hidden card\"><h2>Local Forecast History</h2><p>Saved forecasts and their original model/data/scenario versions persist through reloads and updates. They are never silently recalculated using new data. This browser\u2019s records are not an authenticated server audit.</p><div class=\"actions\"><button id=\"download\" type=\"button\" disabled>Download Forecast Backup</button><button id=\"clearHistory\" type=\"button\">Clear forecast history</button><button id=\"undoClearHistory\" type=\"button\" hidden>Undo clear</button></div><div id=\"forecasts\" class=\"table-scroll\"></div></section>\n<section id=\"view-insights\" class=\"view hidden card\"><h2>Historical Accuracy</h2><label>Account View<select id=\"accuracyAccount\"></select></label><button id=\"showAccuracy\" type=\"button\">Show published historical metrics</button><div id=\"accuracySummary\"></div><div class=\"table-scroll\"><table><thead><tr><th>Scope / model</th><th>MAE</th><th>MAPE</th><th>Visits</th></tr></thead><tbody id=\"accuracyRows\"></tbody></table></div><p class=\"small muted\">These are published aggregate evidence, not a new browser backtest. Raw historical visits are not available to visitors.</p></section>\n<footer id=\"siteFooter\">Imports, retained histories, source workbooks and backups stay in the local administration app. Google sign-in and the email list control the interface only. Static derived planning data is publicly downloadable.</footer></main>";
 const $=id=>document.getElementById(id),el=(tag,text)=>{const e=document.createElement(tag);if(text!=null)e.textContent=String(text);return e},hours=v=>{const m=Math.round(v*60);return Math.floor(m/60)+'h '+String(m%60).padStart(2,'0')+'m'},names=ids=>ids.map(id=>snapshot.persons.find(p=>p.key===id)?.name||'Former/unknown employee').join(', ');
 const key='badger-planner-v3:'+new URL('.',location.href).pathname+':'+(session.user?.uid||'local-review'),known=new Set(snapshot.persons.map(p=>p.key));let state={},storageOK=true;
 try{state=JSON.parse(localStorage.getItem(key)||'{}')}catch{state={};storageOK=false}
 state=Object.fromEntries(Object.entries(state).filter(([name])=>['forecasts','draft','storePlans','filters','autoSave','view','compare'].includes(name)));
