 let selected=new Set(),available=new Set(),saved=Array.isArray(state.forecasts)?state.forecasts.filter(f=>f?.plan?.date&&Number.isFinite(f?.prediction?.displayHours)):[],last=null,modeOverride='default',calcTimer=null,saveTimer=null,seq=0,allocEpoch=0,stopped=false,allocationResult=null,clearBackup=null;
 const today=new Date().toLocaleDateString('en-CA'),defaultDate=today<snapshot.cutoff?snapshot.cutoff:today>snapshot.validThrough?snapshot.validThrough:today;
 const chosen=id=>[...$(id).selectedOptions].map(o=>o.value),setChosen=(id,values)=>{for(const o of $(id).options)o.selected=values.includes(o.value)};
 function tell(text,error=false){$('notice').textContent=text;$('notice').className=error?'error':''}
 function persist(){state.forecasts=saved;try{localStorage.setItem(key,JSON.stringify(state));storageOK=true}catch{storageOK=false;$('saveStatus').textContent='Browser storage is unavailable or full. Download a forecast backup; history cannot currently be persisted.'}}
 function options(id,items,placeholder){const node=$(id),old=node.value,olds=new Set(chosen(id));node.replaceChildren();if(placeholder){const o=el('option',placeholder);o.value='';node.append(o)}for(const item of items){const o=el('option',item.name);o.value=item.key;if(node.multiple)o.selected=olds.has(item.key);node.append(o)}if(!node.multiple&&items.some(i=>i.key===old))node.value=old;}
 function readPlan(){return {storeKey:$('store').value,date:$('date').value,startTime:$('time').value,employees:[...selected],roles:{supervisor:$('supervisor').value,rx:chosen('rx'),training:chosen('training'),earlyLate:chosen('earlyLate')},modes:{supervisor:$('supervisorMode').value,rx:$('rxMode').value,training:$('trainingMode').value,earlyLate:$('earlyLateMode').value},countingMode:modeOverride,useRecentAccountProduction:$('recentProduction').checked,shrink:{percent:Number($('shrinkPercent').value)||0,mode:$('shrinkMode').value,employeeIds:[...$('shrinkEmployees').querySelectorAll('input:checked')].map(x=>x.value)},model:$('fullOnsiteMode').checked?'integrated':'reference',targetValue:Number($('targetValue').value)||0,goalMode:$('planningMode').value};}
 function saveDraft(){state.draft=persistentDraft(readPlan(),snapshot);state.storePlans=state.storePlans||{};if(state.draft.stableStore)state.storePlans[state.draft.stableStore]=state.draft;state.filters={account:$('account').value,employee:$('employeeFilter').value,store:$('storeFilter').value};state.autoSave=$('autoSave').checked;persist();}
 function summary(){const st=snapshot.stores.find(s=>s.key===$('store').value);if(!st){$('storeSummary').textContent='Select a store to view history.';$('countingModeHint').textContent='';$('lastCrewSummary').textContent='Select a store.';return}
  const history=st.context?.fixed.historyCount??st.scenario.variants.default?.historyCount??0;$('storeSummary').textContent=history+' prior reference visits. Choose the prediction date and planned start manually.';
  $('countingModeHint').textContent='Latest verified counting mode: '+(st.scenario.defaultMode===true?'Modas':st.scenario.defaultMode===false?'regular':'unknown')+'. Override compares the original reference assumptions.';
  $('lastCrewSummary').textContent=st.lastCrew.employees.length?names(st.lastCrew.employees)+' · current roster members only. Actual historical crew may include former employees.':'No current employees from the latest crew are available.';
 }
 function stores(){const list=snapshot.stores.filter(s=>(!$('account').value||s.name.split(' / ')[0]===$('account').value)&&s.name.toLowerCase().includes($('storeFilter').value.toLowerCase()));options('store',list,'Choose a store');$('storeCount').textContent=list.length+' stores available';summary()}
 function renderRoles(){const people=snapshot.persons.filter(p=>selected.has(p.key)),oldShrink=new Set([...$('shrinkEmployees').querySelectorAll('input:checked')].map(x=>x.value));for(const id of ['supervisor','rx','training','earlyLate'])options(id,people,id==='supervisor'?'Not assigned — exploratory':null);$('shrinkEmployees').replaceChildren();for(const p of people){const label=el('label'),input=el('input');input.type='checkbox';input.value=p.key;input.checked=oldShrink.has(p.key);input.addEventListener('change',changed);label.append(input,el('span',p.name));$('shrinkEmployees').append(label)}$('shrinkEmployees').classList.toggle('hidden',$('shrinkMode').value!=='selected');$('crewCount').textContent=people.length+' employees selected';$('selectedCrewSummary').textContent=people.length?people.map(p=>p.name).join(' · '):'No crew selected.';}
 function crew(){const query=$('employeeFilter').value.toLowerCase();$('crew').replaceChildren();for(const p of snapshot.persons.filter(p=>p.name.toLowerCase().includes(query))){const label=el('label'),c=el('input');c.type='checkbox';c.value=p.key;c.checked=selected.has(p.key);c.addEventListener('change',()=>{c.checked?selected.add(p.key):selected.delete(p.key);renderRoles();changed()});label.append(c,el('span',p.name));$('crew').append(label)}if(!$('crew').children.length)$('crew').append(el('p','No crew members match your search. Selected crew is retained.'));renderRoles()}
 function invalidate(){last=null;$('save').disabled=true;$('suggestStaffing').disabled=true;$('prediction').textContent='Select a store, crew and valid date to preview the plan.';$('labor').textContent='—';$('effectiveLabor').textContent='—';$('recommendation').textContent='Choose Store and Crew';$('delta').textContent='';$('production').replaceChildren();$('background').replaceChildren();$('staffingSuggestion').textContent='';$('estimateKind').textContent='';$('referenceComparison').textContent='';$('scenarioExplanation').textContent='';$('historicalRange').textContent='';$('whyEstimate').textContent='';$('goalHint').textContent='Set an optional target to compare the plan.';}
 function changed(){if(stopped)return;seq++;allocEpoch++;clearTimeout(calcTimer);clearTimeout(saveTimer);invalidate();saveDraft();const p=readPlan();if(!p.storeKey||!p.employees.length){tell(p.storeKey?'Choose your crew to calculate automatically.':'Choose a store to begin.');return}tell('Updating plan preview…');const token=seq;calcTimer=setTimeout(()=>calculate(token),120)}
 function validate(p){if(today>snapshot.validThrough)throw Error('This planning week has expired. The administrator must build the new week.');if(!p.storeKey)throw Error('Select a store.');if(!p.employees.length)throw Error('Choose 1-50 current employees.');if(!$('planForm').checkValidity())throw Error('Check the date, start time, target and shrink fields.');const st=snapshot.stores.find(s=>s.key===p.storeKey);if(st.needsRx&&!p.roles.rx.length)throw Error('Assign at least one RX employee for this store.');}
 function calculate(token=seq){if(stopped||token!==seq)return;try{const p=readPlan();validate(p);const r=predictPlan(snapshot,p);if(r.status!=='ok')throw Error(r.message||'No supported reference history for this plan.');last={plan:p,prediction:r};renderPrediction(p,r);$('save').disabled=!futureStart(p)||!p.roles.supervisor;$('suggestStaffing').disabled=!(p.targetValue>0);tell('Plan preview updated. '+(r.adjusted?'Manual scenario assumptions are active.':r.estimateKind+'.'));if($('autoSave').checked&&futureStart(p)&&p.roles.supervisor){$('saveStatus').textContent='Waiting to save after input changes settle…';saveTimer=setTimeout(()=>{if(token===seq&&last)saveForecast(true)},650)}else $('saveStatus').textContent=p.roles.supervisor?'This preview starts in the past. It is exploratory and will not be saved as a previsit forecast.':'Assign a supervisor to save a previsit forecast.';}catch(error){invalidate();tell(error.message,true)}}
 function renderPrediction(p,r){const big=el('div',hours(r.displayHours));big.className='big';big.dataset.hours=r.displayHours;$('prediction').replaceChildren(big,el('p',r.crewSize+' selected employees · full onsite time'));for(const warning of r.warnings||[])$('prediction').append(el('p',warning));$('estimateKind').textContent=r.estimateKind;$('labor').textContent=r.laborHours.toFixed(1)+' hrs';$('effectiveLabor').textContent=r.effectiveCountingHours.toFixed(1)+' hrs';$('recommendation').textContent=r.recommendation;$('delta').textContent=r.delta===null?'Set a goal to compare the plan.':(r.delta>=0?'Above':'Below')+' goal by '+Math.abs(r.delta).toFixed(2)+' hours';$('goalHint').textContent=$('delta').textContent;
  $('referenceComparison').textContent='Integrated base: '+(r.mainAvailable===false?'no mapped full history':hours(r.main.predictedHours))+' · Original reference under your assumptions: '+hours(r.reference.onSiteDuration);$('scenarioExplanation').textContent=r.scenarioRule;
  const error=r.historicalCalibration;$('historicalRange').textContent=error?.count>=20?'Archived reference calibration: '+error.count+' visits; 10th–90th error offsets '+error.p10.toFixed(2)+' to +'+error.p90.toFixed(2)+' hours. These offsets are not a validated interval for this refreshed/scenario estimate.':'Not enough archived calibration evidence for a measured error range. No interval is fabricated.';
  $('whyEstimate').textContent='The integrated model estimates arrival through departure using validated scan/attendance history. The original reference uses '+r.reference.baselineSource+' and '+r.reference.matchingHistoryCount+' references. Labor Hours assumes all selected people remain for the whole estimated visit. Contributions alter counting capacity, not attendance headcount. '+(!r.reference.supervisorComparable?'Some reference crews omit supervisor production; comparisons exclude supervisors on both sides. ':'')+(p.roles.supervisor?'':'No supervisor is assigned; this is exploratory.');
  $('production').replaceChildren();r.crew.forEach((e,i)=>{const row=el('tr'),role=e.id===p.roles.supervisor?'Supervisor':p.roles.rx.includes(e.id)?'RX':p.roles.training.includes(e.id)?'Training':p.roles.earlyLate.includes(e.id)?'Early/Late':'Counter',arrow=e.recentSpeed>e.standardSpeed*1.01?'↑':e.recentSpeed<e.standardSpeed*.99?'↓':'=';for(const value of [i+1,e.name,role+' · '+Math.round(e.factor*100)+'%',Math.round(e.speed).toLocaleString(),arrow+' '+Math.round(e.recentSpeed).toLocaleString(),Math.round(e.effectiveSpeed).toLocaleString(),Math.round(e.predictedPieces).toLocaleString(),e.known?'Observed / shrunk':'Prior fallback'])row.append(el('td',value));$('production').append(row)});
  const st=snapshot.stores.find(s=>s.key===p.storeKey),phase=Number(p.date.slice(5,7))%3,pack=r.reference.pack;$('background').replaceChildren();for(const text of ['Frozen model: '+snapshot.modelVersion+' · '+snapshot.modelSha256.slice(0,12),'Legacy baseline: '+pack.config.baseline+', elasticity '+pack.config.elasticity+'; crew-driven changes remain bounded to the original 0.85–1.20 factors.','Reference scope: '+pack.source+'; counting mode '+(pack.inventoryMode===true?'Modas':pack.inventoryMode===false?'regular':'unknown')+'; inventory type '+pack.typeOfInv,st.context?'Derived typical workload: '+Math.round(st.context.phases[phase].rich.pieces).toLocaleString()+' pieces; '+Math.round(st.context.phases[phase].rich.records).toLocaleString()+' records.':'No mapped full-onsite history; the original attendance-proxy reference is a clearly labelled fallback.','Contribution rules: minimum applicable supervisor/RX/training/early-late factor, then shrink. 100% shrink keeps the original 1% numerical floor; zero-contribution crews are rejected.',r.scenarioRule])$('background').append(el('p',text));}
 function futureStart(p){const when=new Date(p.date+'T'+p.startTime+':00');return Number.isFinite(when.valueOf())&&when>new Date()}
 function saveForecast(automatic=false){if(!last||!futureStart(last.plan)||!last.plan.roles.supervisor)return;const p=last.plan,r=last.prediction,signature=JSON.stringify([persistentDraft(p,snapshot),snapshot.dataFingerprint,snapshot.modelSha256,release.files.planning.sha256]);if(saved.some(f=>f.signature===signature)){$('saveStatus').textContent='This exact plan, assumptions and release are already saved.';return}const st=snapshot.stores.find(s=>s.key===p.storeKey);saved.push({signature,plan:p,stablePlan:persistentDraft(p,snapshot),crewNames:r.crew.map(e=>e.name),storeName:st.name,prediction:{displayHours:r.displayHours,integratedBaseHours:r.mainAvailable===false?null:r.main.predictedHours,referenceHours:r.reference.onSiteDuration,laborHours:r.laborHours,effectiveCountingHours:r.effectiveCountingHours,kind:r.estimateKind},savedAt:new Date().toISOString(),scheduledStart:new Date(p.date+'T'+p.startTime+':00').toISOString(),snapshotFingerprint:snapshot.dataFingerprint,planningSha256:release.files.planning.sha256,modelSha256:snapshot.modelSha256,releaseVersion:release.version});persist();renderHistory();$('saveStatus').textContent=storageOK?(automatic?'Automatically saved':'Saved')+' to this browser with the original model/data/scenario versions.':'Forecast is held in memory because browser storage failed. Download a backup before leaving.';}
