 async function staffing(){if(!last||!(last.plan.targetValue>0))return;const token=seq,p=last.plan,r=last.prediction,candidates=[];$('staffingSuggestion').textContent='Comparing hypothetical crew changes…';const choices=r.delta>=0?snapshot.persons.filter(e=>!selected.has(e.key)).map(e=>({id:e.key,add:true})):p.employees.filter(id=>id!==p.roles.supervisor&&!p.roles.rx.includes(id)).map(id=>({id,add:false}));for(let i=0;i<choices.length;i++){if(token!==seq)return;const c=choices[i],employees=c.add?[...p.employees,c.id]:p.employees.filter(id=>id!==c.id);if(!employees.length)continue;try{const next=predictPlan(snapshot,{...p,employees,roles:{...p.roles,training:p.roles.training.filter(id=>employees.includes(id)),earlyLate:p.roles.earlyLate.filter(id=>employees.includes(id))},shrink:{...p.shrink,employeeIds:p.shrink.employeeIds.filter(id=>employees.includes(id))}});candidates.push({...c,delta:next.delta,hours:next.displayHours,labor:next.laborHours})}catch{}if(i%10===0)await new Promise(resolve=>setTimeout(resolve,0))}candidates.sort((a,b)=>Math.abs(a.delta)-Math.abs(b.delta));if(token!==seq)return;const best=candidates[0];$('staffingSuggestion').textContent=best?(best.add?'Consider adding ':'Consider removing ')+names([best.id])+': hypothetical on-site '+hours(best.hours)+', labor '+best.labor.toFixed(1)+' hrs, goal deviation '+Math.abs(best.delta).toFixed(2)+' hrs. Historical model comparison, not a causal guarantee.':'No feasible one-person change is available.';}
